SELECT DISTINCTROW [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Position, "El. "+[Gesamt Normierung]![Elektrolyseur]+" Pos. "+Format([Gesamt Normierung]![Position],"0") AS Bezeichnung, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].[I Gesamt], ([Gesamt Normierung]![I Gesamt]/GetGewFlaeche()) AS i, [Gesamt Normierung].Cc, [Gesamt Normierung].[t An], [Gesamt Normierung].[t Ka], ([Gesamt Normierung]![t An]+[Gesamt Normierung]![t Ka])/2 AS tm, [Gesamt Normierung].Ui, Um.[Mittelwert von Ui], [Gesamt Normierung].Un AS Unalt2, TempKorrElement([tm],[Mittelwert von Ui],[Ui]) AS ti, [tm]-([Mittelwert von Ui]-[Ui])*30 AS tiAlt, UnBer([Ui],[i],[ti],[Gesamt Normierung]![Cc]) AS Un, [Gesamt Normierung].Unalt, [Gesamt Normierung].UnVgl3, [Gesamt Normierung].iRef, [Gesamt Normierung].tKorr, [Gesamt Normierung].cKorr
FROM tblGewDaten, tblGewElementeUnCeSpc INNER JOIN ([Gesamt Normierung] INNER JOIN Um ON ([Gesamt Normierung].Datum = Um.Datum) AND ([Gesamt Normierung].Elektrolyseur = Um.Elektrolyseur)) ON (tblGewElementeUnCeSpc.Position = [Gesamt Normierung].Position) AND (tblGewElementeUnCeSpc.Bezeichnung = [Gesamt Normierung].Elektrolyseur)
WHERE ((([Gesamt Normierung].Datum)>=[tblGewDaten].[Anfangsdatum] And ([Gesamt Normierung].Datum)<=[tblGewDaten].[Enddatum]) AND (([Gesamt Normierung].[I Gesamt]) Is Not Null) AND (([Gesamt Normierung].Cc) Is Not Null) AND (([Gesamt Normierung].[t An]) Is Not Null) AND (([Gesamt Normierung].[t Ka]) Is Not Null) AND (([Gesamt Normierung].Ui) Is Not Null))
ORDER BY [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Position, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit;
